import{_ as i,o as a,c as n,ag as l}from"./chunks/framework.PVHj0As1.js";const e="/pub-blog/assets/TwoLevelLink.nxUYVzMJ.gif",t="/pub-blog/assets/image-20250717230556538.CYf7HbpT.png",h="/pub-blog/assets/image-20250717230949868.BtvrBNs5.png",p="/pub-blog/assets/image-20250717231014748.kp212e_D.png",F=JSON.parse('{"title":"03-万少带你精读鸿蒙codelabs——基于List组件实现二级联动效果","description":"","frontmatter":{},"headers":[],"relativePath":"万少带你精读鸿蒙codelabs/03-万少带你精读鸿蒙codelabs——基于List组件实现二级联动效果/03-万少带你精读鸿蒙codelabs——基于List组件实现二级联动效果.md","filePath":"万少带你精读鸿蒙codelabs/03-万少带你精读鸿蒙codelabs——基于List组件实现二级联动效果/03-万少带你精读鸿蒙codelabs——基于List组件实现二级联动效果.md","lastUpdated":1756109794000,"__rawMarkdown":"# 03-万少带你精读鸿蒙codelabs——基于List组件实现二级联动效果\\n\\n> 原文链接 https://developer.huawei.com/consumer/cn/codelabsPortal/carddetails/tutorials_NEXT-SecondLevelLinkage\\n\\n## 1. 功能介绍\\n本案例实现了一个课程分类展示系统，主要包含以下核心功能：\\n- 双栏联动布局（左侧分类导航栏+右侧课程列表）\\n- 分类切换时自动滚动到对应课程区域\\n- 滚动课程列表时自动同步分类选中状态\\n- 加载状态管理（显示Loading提示）\\n- 自适应屏幕布局\\n\\n![TwoLevelLink](assets/TwoLevelLink.gif)\\n\\n## 2. 关键组件\\n| 组件/装饰器                                                  | 作用说明                                         |\\n| ------------------------------------------------------------ | ------------------------------------------------ |\\n| [List](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-layout-development-create-list) | 构建可滚动列表容器（左侧分类列表和右侧课程列表） |\\n| [ForEach](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-rendering-control-foreach) | 循环渲染分类和课程条目                           |\\n| [@State](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-state) | 管理组件状态（当前选中分类、数据加载状态）       |\\n| [@Builder](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-builder) | 构建可复用的UI片段（列表分组头部）               |\\n| [Scroller](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-scroll#scroller) | 控制列表滚动行为                                 |\\n| [ListItemGroup](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-listitemgroup) | 创建带分组的列表项                               |\\n| [StickyStyle.Header](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list#stickystyle9%E6%9E%9A%E4%B8%BE%E8%AF%B4%E6%98%8E) | 实现分组头部粘滞效果                             |\\n\\n## 3. 逻辑思路\\n\\n\\n主要交互流程说明：\\n1. **初始化阶段**：通过setTimeout模拟异步数据加载，设置500ms延迟（实际开发中应替换为真实API调用）\\n2. **布局渲染**：使用Row容器嵌套两个List实现双栏布局，左侧固定宽度，右侧自适应剩余空间\\n3. **分类联动**：\\n    - 点击左侧分类时，通过`scrollToIndex`控制右侧列表滚动\\n    - 滚动右侧列表时，通过`onScrollIndex`监听首项索引，反向控制左侧分类选中状态\\n4. **性能优化**：\\n    - 使用`sticky`属性实现分组头部粘滞\\n    - 设置`scrollBar(BarState.Off)`隐藏滚动条\\n    - 通过`edgeEffect(EdgeEffect.None)`禁用边缘发光效果\\n\\n**示例图**\\n\\n![image-20250717230556538](assets/image-20250717230556538.png)\\n\\n### 初始化阶段\\n\\n**初始化阶段**：通过setTimeout模拟异步数据加载，设置500ms延迟（实际开发中应替换为真实API调用）\\n\\n- `currentClassify`：当前选中的分类索引。\\n- `requestSuccess`：数据加载是否成功的状态标志。\\n- `classifyList`：分类数据列表。\\n- `classifyScroller`和`scroller`：用于控制分类列表和课程列表的滚动。\\n\\n```typescript\\n@State currentClassify: number = 0; // selected classify index.\\n@State requestSuccess: boolean = false; // is loading data.\\nprivate classifyList: Array<ClassifyModel> = [];\\nprivate classifyScroller: Scroller = new Scroller();\\nprivate scroller: Scroller = new Scroller();\\n```\\n\\n---\\n\\n```typescript\\n  aboutToAppear() {\\n    // loading data.\\n    setTimeout(() => {\\n      this.classifyList = ClassifyViewModel.getLinkData();\\n      this.requestSuccess = true;\\n    }, Constants.LOADING_DURATION);\\n  }\\n```\\n\\n### 布局渲染\\n\\n- `build`方法用于构建页面的UI布局。\\n- 当数据加载成功时，使用`List`组件渲染分类列表和课程列表。\\n- `classifyList`用于渲染分类列表，每个分类项使用`ClassifyItem`组件展示。\\n- `classifyList`中的每个分类项包含多个课程项，使用`ListItemGroup`组件按分类分组展示。\\n- 当数据加载失败时，显示一个加载中的提示文本。\\n\\n```typescript\\nbuild() {\\n    Row() {\\n      if (this.requestSuccess) {\\n        List({ scroller: this.classifyScroller }) {\\n          ForEach(this.classifyList, (item: ClassifyModel, index?: number) => {\\n            ListItem() {\\n              ClassifyItem({\\n                classifyName: item.classifyName,\\n                isSelected: this.currentClassify === index,\\n                onClickAction: () => {\\n                  if (index !== undefined) {\\n                    this.classifyChangeAction(index, true);\\n                  }\\n                }\\n              })\\n            }\\n          }, (item: ClassifyModel) => item.classifyName.toString() + this.currentClassify)\\n        }\\n        .height(Constants.FULL_PERCENT)\\n        .width($r(\'app.float.classify_item_width\'))\\n        .backgroundColor($r(\'app.color.classify_background\'))\\n        .scrollBar(BarState.Off)\\n\\n        List({ scroller: this.scroller }) {\\n          ForEach(this.classifyList, (classifyItem: ClassifyModel) => {\\n            ListItemGroup({\\n              header: this.ClassifyHeader(classifyItem.classifyName),\\n              space: Constants.COURSE_ITEM_PADDING\\n            }) {\\n              ForEach(classifyItem.courseList, (courseItem: CourseModel) => {\\n                ListItem() {\\n                  CourseItem({ itemStr: JSON.stringify(courseItem) })\\n                }\\n              }, (courseItem: CourseModel) => `${courseItem.courseId}`)\\n            }\\n          }, (item: ClassifyModel) => `${item.classifyId}`)\\n        }\\n        .height(Constants.FULL_PERCENT)\\n        .width(Constants.FULL_PERCENT)\\n        .padding({ left: $r(\'app.float.item_padding_left\'), right: $r(\'app.float.course_item_padding\') })\\n        .sticky(StickyStyle.Header)\\n        .layoutWeight(1)\\n        .edgeEffect(EdgeEffect.None)\\n        .onScrollIndex((start: number) => this.classifyChangeAction(start, false))\\n      } else {\\n        Text($r(\'app.string.loading\'))\\n          .fontFamily($r(\'app.string.hei_ti_medium\'))\\n          .textAlign(TextAlign.Center)\\n          .height(Constants.FULL_PERCENT)\\n          .width(Constants.FULL_PERCENT)\\n      }\\n    }\\n    .backgroundColor($r(\'app.color.base_background\'))\\n  }\\n```\\n\\n### 分类联动\\n\\n- 点击左侧分类时，通过`scrollToIndex`控制右侧列表滚动\\n\\n![image-20250717230949868](assets/image-20250717230949868.png)\\n\\n- 滚动右侧列表时，通过`onScrollIndex`监听首项索引，反向控制左侧分类选中状态\\n\\n![image-20250717231014748](assets/image-20250717231014748.png)\\n\\n### 性能优化\\n\\n- 使用`sticky`属性实现分组头部粘滞\\n- 设置`scrollBar(BarState.Off)`隐藏滚动条\\n- 通过`edgeEffect(EdgeEffect.None)`禁用边缘发光效果\\n\\n\\n\\n\\n\\n## 总结\\n\\n如果你兴趣想要了解更多的开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。"}'),k={name:"万少带你精读鸿蒙codelabs/03-万少带你精读鸿蒙codelabs——基于List组件实现二级联动效果/03-万少带你精读鸿蒙codelabs——基于List组件实现二级联动效果.md"};function r(E,s,d,c,o,g){return a(),n("div",null,[...s[0]||(s[0]=[l("",31)])])}const u=i(k,[["render",r]]);export{F as __pageData,u as default};
